const msg = $json;

function blockText(block) {
  const parts = [];
  if (block.text && block.text.text) parts.push(block.text.text);
  if (block.fields) block.fields.forEach(f => { if (f.text) parts.push(f.text); });
  if (block.elements) block.elements.forEach(e => { if (e.text) parts.push(e.text); });
  return parts.join('\n');
}

function fullText(m) {
  if (!m.blocks) return m.text || '';
  return m.blocks.map(blockText).join('\n');
}

const HEADINGS = ['Entities', 'API traffic', 'Emails', 'Suspicious activity', 'Estimated AWS cost'];

function extractSection(text, heading, nextHeadings) {
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const startRe = new RegExp('\\*' + esc(heading) + '\\*');
  const startMatch = startRe.exec(text);
  if (!startMatch) return '';
  const startIdx = startMatch.index + startMatch[0].length;
  let endIdx = text.length;
  for (const h of nextHeadings) {
    const re = new RegExp('\\*' + esc(h) + '\\*');
    const m = re.exec(text.slice(startIdx));
    if (m) {
      const idx = startIdx + m.index;
      if (idx < endIdx) endIdx = idx;
    }
  }
  return text.slice(startIdx, endIdx);
}

function parseEntities(sec) {
  const rows = {};
  const re = /^(Customers|Startups|Cases)\s+(\d+)\s+(\d+)\s+(\d+)\s+([+-]?\d+)/gm;
  let m;
  while ((m = re.exec(sec))) {
    rows[m[1]] = { total: +m[2], active: +m[3], deleted: +m[4], last7d: +m[5] };
  }
  return rows;
}

function parseTraffic(sec) {
  const last7 = /Last 7 days\*\s*\n(\d[\d,]*)\s*requests/.exec(sec);
  const month = /This month\*\s*\n(\d[\d,]*)\s*requests/.exec(sec);
  const compact = /last 7 days:\s*\*(\d[\d,]*)\*[\s\S]*?this month:\s*\*(\d[\d,]*)\*/.exec(sec);
  const functions = {};
  const fnRe = /^(\S+Function)\s+(\d+)\s+([\d,]+)$/gm;
  let m;
  while ((m = fnRe.exec(sec))) {
    functions[m[1]] = +m[2];
  }
  return {
    last7dRequests: last7 ? +last7[1].replace(/,/g, '') : (compact ? +compact[1].replace(/,/g, '') : null),
    monthRequests: month ? +month[1].replace(/,/g, '') : (compact ? +compact[2].replace(/,/g, '') : null),
    functions
  };
}

function parseTrafficDaily(sec) {
  const days = [];
  const re = /^(\w{3})\s+(\d{2}-\d{2})\s+[█░]+\s+(\d+)\s*$/gm;
  let m;
  while ((m = re.exec(sec))) {
    days.push({ dow: m[1], date: m[2], requests: +m[3] });
  }
  return days;
}

function parseEmails(sec) {
  const types = {};
  const lines = sec.split('\n');
  const rowRe = /^(.{3,}?)\s{2,}(\d+)\s+(\d+)$/;
  lines.forEach(line => {
    const m = rowRe.exec(line);
    if (m && !/^Type\s/.test(m[1])) {
      types[m[1].trim()] = +m[2];
    }
  });
  return types;
}

function parseSuspicious(sec) {
  const alerts = [];
  const alertRe = /:(red_circle|large_orange_circle|white_circle):\s*\*(\d+)\*\s*([^\n]+)/g;
  let m;
  while ((m = alertRe.exec(sec))) {
    alerts.push({ severity: m[1], count: +m[2], description: m[3].trim() });
  }
  const ips = [];
  const ipRe = /^(\d{1,3}(?:\.\d{1,3}){3})\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)$/gm;
  while ((m = ipRe.exec(sec))) {
    ips.push({ ip: m[1], requests: +m[2], err4xx: +m[3], err5xx: +m[4], throttled429: +m[5] });
  }
  return {
    alerts,
    topIps: ips,
    total5xx: alerts.filter(a => /5xx/i.test(a.description)).reduce((s, a) => s + a.count, 0),
    total429: alerts.filter(a => /429/.test(a.description)).reduce((s, a) => s + a.count, 0),
    total4xx: ips.reduce((s, ip) => s + ip.err4xx, 0)
  };
}

function parseCost(sec) {
  if (/Unavailable/i.test(sec)) return { available: false };
  const mtd = /Month to date\*\s*\n\$([\d.,]+)/.exec(sec) || /Total \*\$([\d.,]+)\*/.exec(sec);
  const projected = /Projected month end\*\s*\n\$([\d.,]+)/.exec(sec) || /projected month end \*\$([\d.,]+)\*/.exec(sec);
  return {
    available: true,
    monthToDate: mtd ? +mtd[1].replace(/,/g, '') : null,
    projectedMonthEnd: projected ? +projected[1].replace(/,/g, '') : null
  };
}

const text = msg.text || '';
const dateMatch = /—\s*(\d{4}-\d{2}-\d{2})/.exec(text);
const date = dateMatch ? dateMatch[1] : new Date(parseFloat(msg.ts) * 1000).toISOString().slice(0, 10);
const full = fullText(msg);

const entities = parseEntities(extractSection(full, 'Entities', HEADINGS.filter(h => h !== 'Entities')));
const trafficSec = extractSection(full, 'API traffic', HEADINGS.filter(h => h !== 'API traffic'));
const traffic = parseTraffic(trafficSec);
const trafficDaily = parseTrafficDaily(trafficSec);
const emailTypes = parseEmails(extractSection(full, 'Emails', HEADINGS.filter(h => h !== 'Emails')));
const suspicious = parseSuspicious(extractSection(full, 'Suspicious activity', HEADINGS.filter(h => h !== 'Suspicious activity')));
const cost = parseCost(extractSection(full, 'Estimated AWS cost', HEADINGS.filter(h => h !== 'Estimated AWS cost')));

const topIp = [...suspicious.topIps].sort((a, b) => b.requests - a.requests)[0] || {};

// Identify the IP(s) actually responsible for 5xx errors (may differ from the top-traffic IP)
const top5xxIps = [...suspicious.topIps].filter(ip => ip.err5xx > 0).sort((a, b) => b.err5xx - a.err5xx).slice(0, 5);
const top5xxIp = top5xxIps[0] || {};

return [{
  json: {
    reportDate: date,
    messageTs: msg.ts,
    last7dRequests: traffic.last7dRequests,
    monthRequests: traffic.monthRequests,
    total5xx: suspicious.total5xx,
    total429: suspicious.total429,
    total4xx: suspicious.total4xx,
    alertCount: suspicious.alerts.length,
    costMtd: cost.available ? cost.monthToDate : null,
    costProjected: cost.available ? cost.projectedMonthEnd : null,
    customersTotal: entities.Customers ? entities.Customers.total : null,
    startupsTotal: entities.Startups ? entities.Startups.total : null,
    casesTotal: entities.Cases ? entities.Cases.total : null,
    topIp: topIp.ip || null,
    topIpRequests: topIp.requests || null,
    top5xxIp: top5xxIp.ip || null,
    top5xxIpErr5xx: top5xxIp.err5xx || null,
    top5xxIpRequests: top5xxIp.requests || null,
    top5xxBreakdownJson: JSON.stringify(top5xxIps),
    lambdaFunctionsJson: JSON.stringify(traffic.functions),
    emailTypesJson: JSON.stringify(emailTypes),
    trafficDailyJson: JSON.stringify(trafficDaily)
  }
}];

const current = $('Parse Report').first().json;
const history = $input.all().map(i => i.json).filter(r => r.reportDate !== current.reportDate);

function avg(arr, key) {
  const vals = arr.map(r => r[key]).filter(v => typeof v === 'number');
  if (!vals.length) return null;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

const avg5xx = avg(history, 'total5xx');
const avgCost = avg(history, 'costMtd');
const avgMonthReq = avg(history, 'monthRequests');

const reasons = [];

if (avg5xx !== null && current.total5xx > avg5xx * 2 && (current.total5xx - avg5xx) >= 10) {
  let reason = '5xx errors (' + current.total5xx + ') more than 2x the trailing average (' + avg5xx.toFixed(1) + ')';
  if (current.top5xxIp) {
    reason += ' — top offender: ' + current.top5xxIp + ' (' + current.top5xxIpErr5xx + ' of the 5xx, ' + current.top5xxIpRequests + ' total reqs today)';
  }
  reasons.push(reason);
}
if (avgCost !== null && current.costMtd !== null && avgCost > 0 && current.costMtd > avgCost * 1.5) {
  reasons.push('Cost MTD ($' + current.costMtd + ') is 50%+ above trailing average ($' + avgCost.toFixed(2) + ')');
}
if (avgMonthReq !== null && current.monthRequests !== null && avgMonthReq > 0 && current.monthRequests > avgMonthReq * 3) {
  reasons.push('Monthly request volume spiked to ' + current.monthRequests + ' vs average ' + avgMonthReq.toFixed(0));
}
const knownIps = new Set(history.map(r => r.topIp).filter(Boolean));
if (current.topIp && history.length >= 3 && !knownIps.has(current.topIp)) {
  reasons.push('New top offending IP not seen in recent history: ' + current.topIp + ' (' + current.topIpRequests + ' reqs)');
}

return [{
  json: Object.assign({}, current, {
    anomalyFlag: reasons.length > 0,
    anomalyReason: reasons.join(' | ')
  })
}];

