const messages = $input.all().map(i => i.json);
const reports = messages.filter(m => (m.text || '').startsWith('SolveStack stats report'));
if (!reports.length) return [];
reports.sort((a, b) => parseFloat(b.ts) - parseFloat(a.ts));
return [{ json: reports[0] }];

const images = $json.images || [];
const current = $('Store Row').first().json;
const historyRaw = $('Get Recent History').all().map(i => i.json);
const map = {};
historyRaw.forEach(r => { map[r.reportDate] = r; });
map[current.reportDate] = current;
const rows = Object.values(map).sort((a, b) => a.reportDate.localeCompare(b.reportDate)).slice(-7);

function fmtNum(v) { return (v === null || v === undefined) ? '—' : v; }
function imgFor(key) { const i = images.find(x => x.key === key); return i ? i.permalink : ''; }

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const generatedAt = now.getUTCFullYear() + '-' + pad(now.getUTCMonth() + 1) + '-' + pad(now.getUTCDate()) + ' ' + pad(now.getUTCHours()) + ':' + pad(now.getUTCMinutes()) + ' UTC';

const topIpLines = rows.map(r => '- ' + r.reportDate + ': ' + (r.topIp || '—') + ' (' + fmtNum(r.topIpRequests) + ' requests)').join('\n');

const chartDefinitions = '### What each chart shows\n' +
  '- **API traffic**: real daily request counts for the trailing 7 days, read directly from the latest report’s own per-day breakdown (not accumulated across days).\n' +
  '- **Busiest Lambda functions**: 7-day call counts for the top Lambda functions by traffic.\n' +
  '- **Emails sent**: 7-day counts of emails sent, broken down by email type.\n' +
  '- **Suspicious activity**: daily counts of 5xx errors (server-side failures, usually a Lambda/app bug or crash — worth checking error logs), 4xx errors (client-side errors like 403/404, most often scanner or bot traffic hitting invalid or forbidden paths), and 429s (requests rejected by rate limiting, meaning a client or IP hit too many requests too fast).\n' +
  '- **Top offending IP by day**: the single IP address with the highest request count in each day’s Suspicious activity table, along with how many requests it made that day. A repeat entry across multiple days means the same source kept showing up as the top talker; a new IP appearing here (especially one not seen in the recent history) is what triggers the anomaly detector’s “new top offending IP” rule.\n' +
  '- **Estimated AWS cost**: month-to-date spend and the projected cost by month end.\n';

const anomalyCriteria = '### When is a day flagged as an anomaly?\n' +
  'A day is flagged if any of the following hold, compared against the trailing average of the prior stored days:\n' +
  '- **5xx errors**: more than 2x the trailing average, and at least 10 more in absolute terms\n' +
  '- **Cost (MTD)**: more than 1.5x the trailing average\n' +
  '- **Monthly request volume**: more than 3x the trailing average\n' +
  '- **Top offending IP**: a new IP not seen as the top IP in at least 3 of the prior stored days\n';

const anomalyResult = current.anomalyFlag
  ? '### Anomaly result for ' + current.reportDate + '\n:rotating_light: **Anomaly detected** — ' + current.anomalyReason
  : '### Anomaly result for ' + current.reportDate + '\n:white_check_mark: **No anomaly detected** — all metrics within normal range.';

const markdown = '## AWS reports — trend\n' +
  '_Report date ' + current.reportDate + ' · generated ' + generatedAt + ' · last ' + rows.length + ' days_\n\n' +
  chartDefinitions + '\n' +
  '### API traffic\n![API traffic](' + imgFor('traffic') + ')\n\n' +
  '### Busiest Lambda functions (7d call count)\n![Busiest Lambda functions](' + imgFor('lambda') + ')\n\n' +
  '### Emails sent (7d count)\n![Emails sent](' + imgFor('emails') + ')\n\n' +
  '### Suspicious activity\n![Suspicious activity](' + imgFor('suspicious') + ')\n\nTop offending IP by day:\n' + topIpLines + '\n\n' +
  '### Estimated AWS cost\n![Estimated AWS cost](' + imgFor('cost') + ')\n\n' +
  anomalyCriteria + '\n' + anomalyResult;

return [{ json: { markdown } }];

const current = $json;
const historyRaw = $('Get Recent History').all().map(i => i.json);
const map = {};
historyRaw.forEach(r => { map[r.reportDate] = r; });
map[current.reportDate] = current;
const rows = Object.values(map).sort((a, b) => a.reportDate.localeCompare(b.reportDate)).slice(-7);

function parseJson(s) { if (!s) return {}; try { return JSON.parse(s); } catch (e) { return {}; } }

const labels = rows.map(r => r.reportDate);

let lambdaKeys = [];
let emailKeys = [];
for (let i = rows.length - 1; i >= 0; i--) {
  const lf = parseJson(rows[i].lambdaFunctionsJson);
  if (Object.keys(lf).length && !lambdaKeys.length) lambdaKeys = Object.keys(lf).slice(0, 4);
  const em = parseJson(rows[i].emailTypesJson);
  if (Object.keys(em).length && !emailKeys.length) emailKeys = Object.keys(em).slice(0, 4);
}

const colors = ['#2563eb', '#dc2626', '#16a34a', '#d97706', '#7c3aed'];

const charts = [];

const trafficDailyRaw = $('Parse Report').first().json.trafficDailyJson;
let trafficDaily = [];
try { trafficDaily = JSON.parse(trafficDailyRaw || '[]'); } catch (e) { trafficDaily = []; }
const trafficLabels = trafficDaily.map(d => d.dow + ' ' + d.date);
const trafficValues = trafficDaily.map(d => d.requests);

charts.push({
  key: 'traffic',
  title: 'API traffic (daily requests, from latest report)',
  fileName: 'api-traffic.png',
  chartConfig: {
    type: 'bar',
    data: { labels: trafficLabels, datasets: [
      { label: 'Requests', data: trafficValues, backgroundColor: colors[0] }
    ] },
    options: { plugins: { title: { display: true, text: 'API traffic — daily requests' } } }
  }
});

charts.push({
  key: 'lambda',
  title: 'Busiest Lambda functions (7d call count)',
  fileName: 'lambda-functions.png',
  chartConfig: {
    type: 'bar',
    data: { labels, datasets: lambdaKeys.map((k, i) => ({ label: k, data: rows.map(r => { const lf = parseJson(r.lambdaFunctionsJson); return lf[k] ?? 0; }), backgroundColor: colors[i % colors.length] })) },
    options: { plugins: { title: { display: true, text: 'Busiest Lambda functions' } } }
  }
});

charts.push({
  key: 'emails',
  title: 'Emails sent (7d count)',
  fileName: 'emails-sent.png',
  chartConfig: {
    type: 'bar',
    data: { labels, datasets: emailKeys.map((k, i) => ({ label: k, data: rows.map(r => { const em = parseJson(r.emailTypesJson); return em[k] ?? 0; }), backgroundColor: colors[i % colors.length] })) },
    options: { plugins: { title: { display: true, text: 'Emails sent' } } }
  }
});

charts.push({
  key: 'suspicious',
  title: 'Suspicious activity (4xx / 5xx / 429)',
  fileName: 'suspicious-activity.png',
  chartConfig: {
    type: 'bar',
    data: { labels, datasets: [
      { label: '5xx errors', data: rows.map(r => r.total5xx), backgroundColor: colors[1] },
      { label: '4xx errors', data: rows.map(r => r.total4xx), backgroundColor: colors[0] },
      { label: '429 rate-limited', data: rows.map(r => r.total429), backgroundColor: colors[3] }
    ] },
    options: { plugins: { title: { display: true, text: 'Suspicious activity' } } }
  }
});

charts.push({
  key: 'cost',
  title: 'Estimated AWS cost',
  fileName: 'aws-cost.png',
  chartConfig: {
    type: 'line',
    data: { labels, datasets: [
      { label: 'Month to date ($)', data: rows.map(r => (r.costMtd === null || r.costMtd === undefined) ? null : r.costMtd), borderColor: colors[2], backgroundColor: colors[2], fill: false },
      { label: 'Projected month end ($)', data: rows.map(r => (r.costProjected === null || r.costProjected === undefined) ? null : r.costProjected), borderColor: colors[4], backgroundColor: colors[4], fill: false }
    ] },
    options: { plugins: { title: { display: true, text: 'Estimated AWS cost' } } }
  }
});

return charts.map(c => ({ json: c }));

const original = $('Build Chart Items').item.json;
return {
  json: {
    key: original.key,
    title: original.title,
    permalink: $json.permalink
  }
};
